  (* [comment removed for export] *)
  Lemma rb_L_rotL : forall m ns ns' (q gpv c : Z) (t0 t1 t2 a3 a5 a6 a7 t3 t4 t5 t6 : word),
    rb_ctx m ns ->
    (rb_rotate_left_full ns h gpv q c ≫= (λ ns2, rb_end ns2 h)) = Some ns' ->
    0 <= q < 2^64 -> 0 <= gpv < 2^64 -> 0 <= c < 2^64 ->
    evt rsegs (POST ns')
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 h) (Z_to_bv 64 q) (Z_to_bv 64 gpv) a3 (Z_to_bv 64 c) a5 a6 a7
               s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
