(* [comment removed for export] *)
Definition REBAL_STACK : Z := 0.

Definition rebal_stmt : Prop := forall (h p : Z) (ns ns' : NS) (fuel : nat) (lo hi : Z) (X : list Z)
    ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  NSR m ns lo hi X -> 0 <= h < 2^64 ->
  rebalance_after_insertion fuel ns h p = Some ns' ->
  stk rsegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp -> bv_unsigned sp <= hi ->
  mem_inv rsegs m ->
  evt rsegs (rebal_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc ns' lo hi X m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz h) (wz p) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_RB_REBALANCE) fc None m (seg_rom rsegs)).

Lemma rebal_spec : rebal_stmt.
Proof.
  intros until m; intros NSR0 HB H ST HC LOSP SPH MI.
  assert (PR : 0 <= p < 2^64).
  { unfold rebalance_after_insertion, rb_entry in H.
    destruct (ns !! p) as [ndp|] eqn:Lp. 2:{ unfold get_parent, load in H. rewrite Lp in H. discriminate. }
    pose proof (NSR_node _ _ _ _ _ _ _ NSR0 Lp) as (_ & _ & _ & [padp CHp]).
    pose proof (rw_cells_bound _ _ _ _ CHp) as PB. rewrite NodeCells_size in PB. lia. }
  unfold P_RB_REBALANCE, wz.
  eapply rb_L_entry; try eassumption; try lia.
  split; [exact NSR0|]. split; [apply munch_refl|]. split; [apply wmono_refl|]. split; assumption.
Qed.
End HCW2.
